(function(){
  function rand(a,b){return a+Math.random()*(b-a);}

  function spawnLeaf(){
    const cx=W()/2;
    const side = Math.random()<0.5 ? 'L':'R';
    let x;
    if(side==='L') x = rand(0, Math.max(0,cx-150));
    else x = rand(cx+150, W());
    return {
      x, y: rand(-60,-10),
      vx: rand(-0.15,0.15),
      vy: rand(0.35,0.7),
      size: rand(9,20),
      rot: rand(0,Math.PI*2),
      rotSpeed: rand(-0.018,0.018),
      swayPhase: rand(0,Math.PI*2),
      swaySpeed: rand(0.012,0.028),
      color: PALETTE[Math.floor(Math.random()*PALETTE.length)],
      trail: [],
      state:'leaf',
      life:0
    };
  }

  let particles = [];
  for(let i=0;i<80;i++){
    let p = spawnLeaf();
    p.y = rand(0,H());
    particles.push(p);
  }

  function drawHands(){
    const cx = W()*0.5, cy = H()*0.88;
    ctx.save();
    ctx.translate(cx,cy);

    let grad = ctx.createRadialGradient(0,-40,10,0,-40,190);
    grad.addColorStop(0, PALETTE[0]+'44');
    grad.addColorStop(1, PALETTE[0]+'00');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(0,-40,190,0,Math.PI*2);
    ctx.fill();

    ctx.lineWidth = 2;
    ctx.strokeStyle = PALETTE[1] + 'cc';
    ctx.fillStyle = PALETTE[1] + '15';

    ctx.beginPath();
    ctx.moveTo(-150,20);
    ctx.quadraticCurveTo(-172,-65,-75,-78);
    ctx.quadraticCurveTo(-8,-82,-4,-22);
    ctx.quadraticCurveTo(-32,12,-150,20);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(150,20);
    ctx.quadraticCurveTo(172,-65,75,-78);
    ctx.quadraticCurveTo(8,-82,4,-22);
    ctx.quadraticCurveTo(32,12,150,20);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    ctx.restore();
  }

  function drawLeaf(p){
    ctx.save();
    ctx.translate(p.x,p.y);
    ctx.rotate(p.rot);
    const s = p.size;
    ctx.beginPath();
    ctx.moveTo(0,-s);
    ctx.bezierCurveTo(s*0.6,-s*0.5, s*0.7,s*0.3, 0,s);
    ctx.bezierCurveTo(-s*0.7,s*0.3, -s*0.6,-s*0.5, 0,-s);
    ctx.closePath();
    ctx.fillStyle = p.color + 'e6';
    ctx.fill();
    ctx.restore();
  }

  function drawNote(p){
    ctx.save();
    ctx.translate(p.x,p.y);
    const a = Math.max(0, 1 - p.life/250);
    ctx.globalAlpha = a;
    ctx.fillStyle = PALETTE[2];
    ctx.shadowColor = PALETTE[0];
    ctx.shadowBlur = 9;
    ctx.beginPath();
    ctx.ellipse(0,0,4,3,Math.PI/6,0,Math.PI*2);
    ctx.fill();
    ctx.fillRect(3,-14,1.3,14);
    ctx.restore();
    ctx.globalAlpha = 1;
  }

  function frame(){
    ctx.clearRect(0,0,W(),H());
    const cx = W()/2;

    drawHands();

    for(let i=particles.length-1;i>=0;i--){
      let p = particles[i];
      if(p.state==='leaf'){
        p.swayPhase += p.swaySpeed;
        p.x += p.vx + Math.sin(p.swayPhase)*0.4;
        p.y += p.vy;
        p.rot += p.rotSpeed;

        p.trail.push({x:p.x,y:p.y});
        if(p.trail.length>6) p.trail.shift();

        for(let k=0;k<p.trail.length;k++){
          const tp = p.trail[k];
          ctx.globalAlpha = (k/p.trail.length)*0.22;
          ctx.fillStyle = p.color;
          ctx.beginPath();
          ctx.arc(tp.x,tp.y,p.size*0.14,0,Math.PI*2);
          ctx.fill();
        }
        ctx.globalAlpha = 1;

        drawLeaf(p);

        const handsY = H()*0.8;
        const dx = p.x - cx;
        if(p.y > handsY && Math.abs(dx) > 95 && Math.abs(dx) < 270){
          p.state = 'note';
          p.life = 0;
          p.vy = -rand(0.3,0.55);
          p.vx = (dx>0?1:-1)*rand(0.04,0.16);
        }
        if(p.y > H()+30){
          particles[i] = spawnLeaf();
        }
      } else {
        p.life++;
        p.x += p.vx;
        p.y += p.vy;
        p.vy -= 0.0018;
        drawNote(p);
        if(p.life>250 || p.y < -30){
          particles[i] = spawnLeaf();
        }
      }
    }
    requestAnimationFrame(frame);
  }
  frame();
})();
